package com.smitnk.projectgrease.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.graphics.vector.group
import androidx.compose.ui.unit.dp

// App icon set (bug #18): path data adapted from Google Material Symbols (Apache-2.0),
// so the app no longer ships the ~30 MB material-icons-extended artifact.
// Names match the old PgIcons.* names to keep call sites readable.
private fun sym(name: String, d: String, viewport: Float = 960f): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, viewport, viewport).apply {
        // Material Symbols use viewBox "0 -960 960 960"; shift down to a 0..960 viewport.
        group(translationY = if (viewport == 960f) 960f else 0f) {
            addPath(addPathNodes(d), fill = SolidColor(Color.Black))
        }
    }.build()

